import{_ as l,a0 as p,w as o,s as h,ao as d,I as n,x as i,a1 as a,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何在 Linux 上让一段时间不活动的用户自动登出 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上让一段时间不活动的用户自动登出 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 上让一段时间不活动的用户自动登出 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上让一段时间不活动的用户自动登出 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20170916 How To Auto Logout Inactive Users After A Period Of Time In Linux","title":"如何在 Linux 上让一段时间不活动的用户自动登出","tag":"201801","desc":""},"relativePath":"201801/20170916 How To Auto Logout Inactive Users After A Period Of Time In Linux.md","filePath":"[post].md"}'),r={name:"201801/20170916 How To Auto Logout Inactive Users After A Period Of Time In Linux.md"};function g(c,s,u,k,b,f){const e=p("Link");return o(),h("div",null,[s[13]||(s[13]=d(`<h1 id="如何在-linux-上让一段时间不活动的用户自动登出" tabindex="-1">如何在 Linux 上让一段时间不活动的用户自动登出 <a class="header-anchor" href="#如何在-linux-上让一段时间不活动的用户自动登出" aria-label="Permalink to “如何在 Linux 上让一段时间不活动的用户自动登出”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2017/09/logout-720x340.jpg" alt=""></p><p>让我们想象这么一个场景。你有一台服务器经常被网络中各系统的很多个用户访问。有可能出现某些用户忘记登出会话让会话保持会话处于连接状态。我们都知道留下一个处于连接状态的用户会话是一件多么危险的事情。有些用户可能会借此故意做一些损坏系统的事情。而你，作为一名系统管理员，会去每个系统上都检查一遍用户是否有登出吗？其实这完全没必要的。而且若网络中有成百上千台机器，这也太耗时了。不过，你可以让用户在本机或 SSH 会话上超过一定时间不活跃的情况下自动登出。本教程就将教你如何在类 Unix 系统上实现这一点。一点都不难。跟我做。</p><h3 id="在-linux-上实现一段时间后自动登出非活动用户" tabindex="-1">在 Linux 上实现一段时间后自动登出非活动用户 <a class="header-anchor" href="#在-linux-上实现一段时间后自动登出非活动用户" aria-label="Permalink to “在 Linux 上实现一段时间后自动登出非活动用户”">​</a></h3><p>有三种实现方法。让我们先来看第一种方法。</p><h4 id="方法-1" tabindex="-1">方法 1： <a class="header-anchor" href="#方法-1" aria-label="Permalink to “方法 1：”">​</a></h4><p>编辑 <code>~/.bashrc</code> 或 <code>~/.bash_profile</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vi ~/.bashrc</span></span></code></pre></div><p>或，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vi ~/.bash_profile</span></span></code></pre></div><p>将下面行加入其中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>TMOUT=100</span></span></code></pre></div><p>这会让用户在停止动作 100 秒后自动登出。你可以根据需要定义这个值。保存并关闭文件。</p><p>运行下面命令让更改生效：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ source ~/.bashrc</span></span></code></pre></div><p>或，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ source ~/.bash_profile</span></span></code></pre></div><p>现在让会话闲置 100 秒。100 秒不活动后，你会看到下面这段信息，并且用户会自动退出会话。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>timed out waiting for input: auto-logout</span></span>
<span class="line"><span>Connection to 192.168.43.2 closed.</span></span></code></pre></div><p>该设置可以轻易地被用户所修改。因为，<code>~/.bashrc</code> 文件被用户自己所拥有。</p><p>要修改或者删除超时设置，只需要删掉上面添加的行然后执行 <code>source ~/.bashrc</code> 命令让修改生效。</p><p>此外，用户也可以运行下面命令来禁止超时：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ export TMOUT=0</span></span></code></pre></div><p>或，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ unset TMOUT</span></span></code></pre></div><p>若你想阻止用户修改该设置，使用下面方法代替。</p><h4 id="方法-2" tabindex="-1">方法 2： <a class="header-anchor" href="#方法-2" aria-label="Permalink to “方法 2：”">​</a></h4><p>以 root 用户登录。</p><p>创建一个名为 <code>autologout.sh</code> 的新文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /etc/profile.d/autologout.sh</span></span></code></pre></div><p>加入下面内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>TMOUT=100</span></span>
<span class="line"><span>readonly TMOUT</span></span>
<span class="line"><span>export TMOUT</span></span></code></pre></div><p>保存并退出该文件。</p><p>为它添加可执行权限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># chmod +x /etc/profile.d/autologout.sh</span></span></code></pre></div><p>现在，登出或者重启系统。非活动用户就会在 100 秒后自动登出了。普通用户即使想保留会话连接但也无法修改该配置了。他们会在 100 秒后强制退出。</p><p>这两种方法对本地会话和远程会话都适用（即本地登录的用户和远程系统上通过 SSH 登录的用户）。下面让我们来看看如何实现只自动登出非活动的 SSH 会话，而不自动登出本地会话。</p><h4 id="方法-3" tabindex="-1">方法 3： <a class="header-anchor" href="#方法-3" aria-label="Permalink to “方法 3：”">​</a></h4><p>这种方法，我们只会让 SSH 会话用户在一段时间不活动后自动登出。</p><p>编辑 <code>/etc/ssh/sshd_config</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /etc/ssh/sshd_config</span></span></code></pre></div><p>添加/修改下面行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ClientAliveInterval 100</span></span>
<span class="line"><span>ClientAliveCountMax 0</span></span></code></pre></div><p>保存并退出该文件。重启 sshd 服务让改动生效。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl restart sshd</span></span></code></pre></div><p>现在，在远程系统通过 ssh 登录该系统。100 秒后，ssh 会话就会自动关闭了，你也会看到下面消息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ Connection to 192.168.43.2 closed by remote host.</span></span>
<span class="line"><span>Connection to 192.168.43.2 closed.</span></span></code></pre></div><p>现在，任何人从远程系统通过 SSH 登录本系统，都会在 100 秒不活动后自动登出了。</p><p>希望本文能对你有所帮助。我马上还会写另一篇实用指南。如果你觉得我们的指南有用，请在您的社交网络上分享，支持 我们！</p><p>祝您好运！</p><hr>`,51)),n("p",null,[s[1]||(s[1]=i("via: ",-1)),a(e,{href:"https://www.ostechnix.com/auto-logout-inactive-users-period-time-linux/"},{default:t(()=>[...s[0]||(s[0]=[i("https://www.ostechnix.com/auto-logout-inactive-users-period-time-linux/",-1)])]),_:1})]),n("p",null,[s[5]||(s[5]=i("作者：",-1)),a(e,{href:"https://www.ostechnix.com/author/sk/"},{default:t(()=>[...s[2]||(s[2]=[i("SK",-1)])]),_:1}),s[6]||(s[6]=i(" 译者：",-1)),a(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[i("lujun9972",-1)])]),_:1}),s[7]||(s[7]=i(" 校对：",-1)),a(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[4]||(s[4]=[i("wxy",-1)])]),_:1})]),n("p",null,[s[10]||(s[10]=i("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[8]||(s[8]=[i("LCTT",-1)])]),_:1}),s[11]||(s[11]=i(" 原创编译，",-1)),a(e,{href:"https://linux.cn/"},{default:t(()=>[...s[9]||(s[9]=[i("Linux中国",-1)])]),_:1}),s[12]||(s[12]=i(" 荣誉推出",-1))])])}const y=l(r,[["render",g]]);export{C as __pageData,y as default};
